import sqlite3
from datetime import datetime, timezone
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("log-incidents")
DB_PATH = "logs.db"


@mcp.tool()
def annotate_log_incident(incident_id: int, note: str, author: str) -> dict:
    if incident_id <= 0:
        return {"ok": False, "error": "incident_id must be positive"}
    if not note.strip() or len(note) > 2000:
        return {"ok": False, "error": "note must be 1-2000 characters"}
    if not author.strip():
        return {"ok": False, "error": "author is required"}
    now = datetime.now(timezone.utc).isoformat()
    with sqlite3.connect(DB_PATH) as conn:
        cur = conn.execute("SELECT 1 FROM incidents WHERE id = ?", (incident_id,))
        if cur.fetchone() is None:
            return {"ok": False, "error": "incident not found"}
        conn.execute("INSERT INTO incident_notes (incident_id, author, note, created_at) VALUES (?, ?, ?, ?)", (incident_id, author, note, now))
        conn.execute("UPDATE incidents SET updated_at = ? WHERE id = ?", (now, incident_id))
    return {"ok": True}

import re
import subprocess
from pathlib import Path
from langchain_core.tools import tool


@tool
def trigger_log_rotation(config_name: str, dry_run: bool = True) -> str:
    if not re.fullmatch(r"[A-Za-z0-9_.-]+", config_name):
        return "error: invalid config name"
    cfg = Path("/etc/logrotate.d") / config_name
    if not cfg.is_file():
        return "error: config not found"
    cmd = ["logrotate", "-f", str(cfg)]
    if dry_run:
        cmd = ["logrotate", "-d", str(cfg)]
    proc = subprocess.run(cmd, capture_output=True, text=True, timeout=120)
    return f"exit={proc.returncode}\n{proc.stdout}{proc.stderr}"
